var output=Path.GetFullPath(args[0]);var repo=Path.GetFullPath(args[1]);Directory.CreateDirectory(Path.GetDirectoryName(output)!);var root=Path.Combine(Path.GetTempPath(),"CommerceErp.MasterTests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
var results=new List<object>();int failed=0;string Op()=>Guid.NewGuid().ToString("N");void Assert(bool b,string message="断言失败"){if(!b)throw new Exception(message);}void Throws<T>(Action a)where T:Exception{try{a();}catch(T){return;}throw new Exception("预期异常未发生："+typeof(T).Name);}
async Task Test(string name,Func<Task> a){try{await a();results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;results.Add(new{name,passed=false,error=e.ToString()});Console.WriteLine("FAIL "+name+": "+e);}}
Task Sync(Action a){a();return Task.CompletedTask;}
(CommerceDatabase Db,MasterDataService Master,OrderService Orders) Fresh(){var db=new CommerceDatabase(Path.Combine(root,Op()),new("合成资料测试企业","测试主仓"));return(db,new(db),new(db));}
MasterResult Sku(MasterDataService m,string code="A",List<SkuComponent>? components=null)=>m.SaveSku(new(Op(),null,0,code,"商品"+code,"件",true,components??[],"新增测试商品"));
MasterResult Shop(MasterDataService m,string external="shop-a")=>m.SaveShop(new(Op(),null,0,Platform.Douyin,external,"测试店铺",true,"新增测试店铺"));
MappingUpdate Map(MasterDataService m,string shop,string sku,string variant="v1",int version=0,bool enabled=true)=>new(new(m.Workspace().TenantId,Platform.Douyin,shop,"p1",variant,sku,1,version,enabled),version);
void Maps(MasterDataService m,params MappingUpdate[] rows){var p=m.PreviewMappings(new(rows.ToList()));Assert(p.Valid,string.Join(";",p.Errors));m.SaveMappings(new(Op(),rows.ToList(),p.Hash,"建立映射"));}
MasterResult Opening(MasterDataService m,OrderService s,string sku,decimal quantity=10){var current=m.Snapshot().Skus.Single(x=>x.Id==sku);var balance=s.Inventory().Single(x=>x.SkuId==sku);var doc=m.CreateOpening(new(Op(),Op(),[new(sku,quantity,current.Version,balance.Version)],"期初测试"));return m.ApproveOpening(doc.Id,new(Op(),doc.Version,"核对期初"));}
SampleOrder Order(MasterDataService m,string shop)=>SeedData.BaseOrder(Platform.Douyin) with{DataKind="manual",TenantId=m.Workspace().TenantId,ShopId=shop,ExternalOrderId=Op(),ShippingFee=0,OrderDiscount=0,PaidAmount=10,Lines=[new(){ExternalLineId="line-1",PlatformProductId="p1",PlatformSkuId="v1",Quantity=1,GoodsAmount=10,MerchantDiscount=0}]};
