string Dispatch(OrderService s,string orderId,string sku)
{
    var order=s.Details(orderId);s.SaveShippingProfile(orderId,new(Op(),order.Summary.Version,new("测试收件人","00000000000","省","市","区","测试地址"),true,"测试员","地址"));s.SaveBarcode(new(Op(),0,"BAR-"+sku,sku,"测试员","条码"));var preparation=s.PrepareShipping(orderId);var shipment=s.CreateShipment(new(Op(),preparation.Lines.Select(l=>new AllocationLine(orderId,l.ExternalLineId,l.Remaining,preparation.Order.Version)).ToList(),"测试员","配单")).Id;
    WarehouseActionRequest Action()=>new(Op(),s.ShipmentDetails(shipment).Summary.Version,"测试员","作业");s.StartPicking(shipment,Action());foreach(var check in s.ShipmentDetails(shipment).Checks)s.ScanShipment(shipment,new(Op(),s.ShipmentDetails(shipment).Summary.Version,"BAR-"+sku,check.Required,"测试员"));s.PackShipment(shipment,Action());s.SaveWaybill(shipment,new(Op(),s.ShipmentDetails(shipment).Summary.Version,"TEST",Op(),"测试员","登记"));s.DispatchShipment(shipment,Action());return s.Deliveries().Single(d=>d.ShipmentId==shipment).Id;
}
await Test("发货连接器忽略取消仍会超时，五次未知后停下并可人工恢复",async()=>
{
    var(db,m,s)=Fresh();var sh=Shop(m);var a=Sku(m);Maps(m,Map(m,sh.Id,a.Id));Opening(m,s,a.Id);var order=s.Import(new(Op(),Order(m,sh.Id)));var job=Dispatch(s,order.OrderId,a.Id);var first=s.Deliveries().Single();s.RetryDelivery(job,new(Op(),first.Version,"测试员","重试"));Throws<ConflictException>(()=>s.RetryDelivery(job,new(Op(),s.Deliveries().Single().Version,"测试员","重复排队")));
    var clock=new ManualClock();var processor=new ShipmentDeliveryProcessor(db,[new NeverShipment()],clock,TimeSpan.FromMilliseconds(40));for(int i=0;i<5;i++){var watch=Stopwatch.StartNew();Assert(await processor.ProcessNextAsync());Assert(watch.Elapsed<TimeSpan.FromSeconds(3));clock.Advance(TimeSpan.FromMinutes(1));}var stopped=s.Deliveries().Single();Assert(stopped.State=="Unknown"&&stopped.Attempts==5&&stopped.NextAttemptAt is null&&!await processor.ProcessNextAsync()&&new WorkerHealthService(db).Read().Exhausted==1);var stock=CommerceDatabase.Json(s.Inventory());s.RetryDelivery(job,new(Op(),stopped.Version,"测试员","核查后恢复"));Assert(await processor.ProcessNextAsync()&&s.Deliveries().Single().Attempts==6&&CommerceDatabase.Json(s.Inventory())==stock);
});
