    var csv=$"流水号,订单号,类型,金额,发生时间,币种,售后编号\r\n{Op()},{input.ExternalOrderId},收入,10,2026-10-01T12:00:00+08:00,CNY,\r\n{Op()},{input.ExternalOrderId},退款,5,2026-10-01T12:00:00+08:00,CNY,{sourceCase}\r\n";s.ImportBill(new(Op(),new(Platform.Douyin,sh.Id,Op(),"test.csv",csv,new(),new(){{"收入",BillKind.Sale},{"退款",BillKind.Refund}}),"测试员","账单"));Assert(s.FinanceOrderDetails(order.OrderId).Order.Profit==5&&s.CheckConsistency().Passed&&s.AuditWarehouse().Passed&&s.AuditAfterSales().Passed&&s.AuditFinance().Passed);s.CreateFinanceExport(new(Op(),Op(),"合成财务",[order.OrderId],"测试员","导出"));Assert(s.FinanceExports().Count==1);
}));
